/**
 * Rate applied to card transactions of the given KST settlement date.
 * On a closed day the default source only carries the previous business day's value (lagged),
 * so the same date is re-queried from the settlement source.
 */
public BigDecimal settlementRate(String currency, LocalDate date) {
    FxQuote q = quote(currency, date);
    if (!q.lagged()) return q.rate();
    return cached(currency, date, FxqClient.SETTLEMENT_SOURCE).rate();
}

private FxQuote cached(String currency, LocalDate date, int source) {
    String pair = CurrencyPairs.pairOf(currency);
    return cache.computeIfAbsent(pair + "@" + date + "#" + source, k -> {
        vendorCalls++;
        return FxqClient.parse(client.rate(pair, date, source));
    });
}

